// Тикет #6a86f7db · 6a86f7dbc7a1b906a507db97 «עיצוב מוקאפ: רשימת התפילות» (S-27, Figma 454:8361) — עבר QA 14.10.2026 (iPhone, TestFlight 1.0.0 (20)).
// ВНИМАНИЕ: префикс #6a86f7db не уникален (6a86f7dbeaab… — другой тикет «שיעורי תורה»); в журнале ключ #6a86f7dbc7a1.
// Кейс .qa/tests/prayer-catalog/PC-04-gold-scrollbar-time-bell.md.
// Требования (реджекты): 11.10 — «פס גלילה דק בצבע זהב, בצד ימין של רשימת הכרטיסים»; 07.10 п.1 — время + колокольчик в строке названия раскрытой карточки.
// Факт 14.10: тонкая золотая полоса справа (6a86f7db-ios-b20-scrollbar-gold-right.png), до и после прокрутки; слева полосы нет
//   (было на iOS 11.10 — серая системная слева). Раскрытая «מנחה»: поля «שעות»/«דקות» и колокольчик слева в строке названия.
// Полоса через accessibility не видна → проверка по пикселям скриншота (золото ≈ rgb(217,168,95)) в полосах 4.5% ширины у правого/левого края.
// Колокольчик не нажимается (данные не меняются) — @prod-safe.
import { driver, expect } from '@wdio/globals';
import { byLabel, byLabelStartsWith, allByText, swipeUp } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import { shown } from '../_lib/app-0710.ts';
import { rectOf, staticText } from '../_lib/app-1310.ts';
import { openPrayersTab, prayersSearchField, goldRowsInStrip, prayerCard } from '../_lib/app-1410.ts';

/** Вертикальная зона списка: от низа поля поиска до верха нижней навигации (в точках). */
async function listZone() {
  const f = await rectOf(await prayersSearchField());
  const { height } = await driver.getWindowSize();
  let tabTop = height * 0.86;
  for (const el of await allByText('בית')) {
    if (!(await el.isDisplayed().catch(() => false))) continue;
    const { y } = await el.getLocation();
    if (y > height * 0.7) tabTop = Math.min(tabTop, y - 40);
  }
  return { y0: f.y + f.height + 8, y1: tabTop };
}

async function checkGoldRight(where: string) {
  const { width } = await driver.getWindowSize();
  const { y0, y1 } = await listZone();
  const right = await goldRowsInStrip(width * 0.955, width, y0, y1);
  const left = await goldRowsInStrip(0, width * 0.045, y0, y1);
  console.log(`[PC-04] ${where}: золото справа ${right} pt, слева ${left} pt (зона ${Math.round(y0)}–${Math.round(y1)})`);
  expect(right).toBeGreaterThanOrEqual(40);   // бегунок видимой длины (14.10 ≈ 1/3 зоны)
  expect(left).toBeLessThan(5);
}

describe('«רשימת התפילות»: полоса прокрутки и время+колокольчик (#6a86f7db)', () => {
  afterEach(async () => { await toHome().catch(() => {}); });

  it('PC-04a Тонкая золотая полоса прокрутки справа от карточек (до и после прокрутки), слева нет #6a86f7db @prod-safe', async () => {
    await openPrayersTab();
    await checkGoldRight('до прокрутки');
    await swipeUp();
    await swipeUp();
    await checkGoldRight('после прокрутки');
  });

  it('PC-04b Раскрытая «מנחה»: «שעות»/«דקות» и колокольчик в строке названия, слева от названия #6a86f7db @prod-safe', async () => {
    await openPrayersTab();
    await (await prayerCard('מנחה')).click();                        // 1-й тап — раскрыть (не открывает молитву)
    const hours = await byLabel('שעות');
    await hours.waitForDisplayed({ timeout: 15000 });
    const minutes = await byLabel('דקות');
    await expect(minutes).toBeDisplayed();

    const title = staticText('מנחה');
    const t = (await shown(title)) ? await rectOf(title) : await rectOf(await prayerCard('מנחה'));
    const tc = t.y + t.height / 2;
    for (const [name, el] of [['שעות', hours], ['דקות', minutes]] as const) {
      const r = await rectOf(el);
      expect({ name, sameRow: Math.abs(r.y + r.height / 2 - tc) <= 60 }).toEqual({ name, sameRow: true });
      expect({ name, leftOfTitle: r.x + r.width <= t.x + 4 }).toEqual({ name, leftOfTitle: true });
    }
    // Колокольчик — switch «תזכורת למנחה» (подпись F-36/RM-09), левее полей времени. TODO калибровка: если подпись иная — по скрину.
    const bell = await byLabelStartsWith('תזכורת למנחה');
    if (await bell.isDisplayed().catch(() => false)) {
      const b = await rectOf(bell);
      const h = await rectOf(hours); const m = await rectOf(minutes);
      expect(b.x + b.width / 2).toBeLessThan(Math.min(h.x, m.x) + 4);
      expect(Math.abs(b.y + b.height / 2 - tc)).toBeLessThanOrEqual(60);
    } else {
      console.log('[PC-04] колокольчик без подписи «תזכורת למנחה» — @manual-check по скрину 6a86f7db-ios-open-card-time-bell.png');
    }
  });
});
